INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srisailam', 2, 5, 'go',
  'Maha Shivaratri Feb 14. Mallikarjuna Jyotirlinga at peak. 250,000+ pilgrims festival day. Lock 4 months ahead.',
  'February is Srisailam''s climactic festival month. Maha Shivaratri Feb 14 2026 — one of India''s biggest Shiva festivals at the Mallikarjuna Jyotirlinga. Pre-festival fortnight 250,000+ daily pilgrim density. Lock rooms 4-6 months ahead.',
  NULL,
  'February in Srisailam is the year''s climactic festival month. Maha Shivaratri falls February 14 in 2026 (verify against the Phalguna-Krishna-Chaturdasi tithi for the year). Among India''s 12 Jyotirlingas, Srisailam''s Mallikarjuna Shivaratri is one of the three most-attended (alongside Kashi Vishwanath Varanasi and Mahakaleshwar Ujjain). The temple runs a continuous 24-hour ritual schedule across the festival day; the four-pahar Rudrabhishekam at 6pm/9pm/midnight/3am draws sequential 50,000-pilgrim waves. Festival-day total: 250,000-400,000 darshan-takers. Pre-festival fortnight density climbs steadily; post-festival three-day tail is when seasoned pilgrims arrive (the queue compresses to 2-4 hours). Rainfall under 10mm, daytime 28-30C, nights 18-19C, humidity 50 percent. NSTR Tiger Reserve at full safari schedule. The Pathala Ganga ghat (850-ft cable car descent, ₹50 round trip) sees pre-festival ritual-bath density. Bhramaramba Shakti Peetha (the co-located Shakti shrine at the temple complex — the only Jyotirlinga-Shakti Peetha pair in India) at full ritual tempo. APTDC Haritha at festival rates ₹4,000-7,000; temple-side guest houses ₹1,500-3,500.'
)
