INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srisailam', 5, 2, 'wait',
  'Rayalaseema heat peak. 26-40C. NSTR safari unsafe. Pathala Ganga descent only pre-dawn. Push to October.',
  'May is the heat dome peak. Daytime 38-40C. NSTR safari last operational fortnight before June 1 closure. Pathala Ganga descent pre-dawn only. Temple inner sanctum cool. Hotel rates at year-low.',
  'May at Srisailam is the Rayalaseema heat peak with NSTR Tiger Reserve closure looming June 1. The full temple-plus-safari experience cannot run cleanly. October opens the proper window.',
  'May in Srisailam is the Rayalaseema heat dome at peak intensity. Daytime 38-40C, nights 26-27C, humidity 50 percent, rainfall under 30mm. Pre-monsoon dust storms hit the second fortnight. The Bhramaramba Mallikarjuna Swamy Temple at full ritual tempo — the cool stone interior holds 32-34C through the mid-day. Suprabhata Seva 4:30am, the standard darshan sequence. The Pathala Ganga ghat 850-ft cable car descent workable 5-9am only; the Krishna river ghat itself remains relatively cool but the cable-car queue at any other hour is brutal. NSTR (Nagarjuna Sagar Srisailam Tiger Reserve) at its last operational fortnight before the June 1 monsoon closure — the afternoon safari slot stopped April; morning safari (6-9am) continues at reduced visitor count. Srisailam Dam viewing platform workable evenings only. APTDC Haritha rates at year-low: ₹2,500-4,500; private guest houses ₹700-1,800. The trip you came for — Jyotirlinga + Shakti Peetha + Tiger Reserve safari + Krishna river ghat — cannot happen cleanly. October-March is dramatically better. Push 5 months.'
)
