INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srisailam', 6, 1, 'skip',
  'SW monsoon hits Nallamala. 24-33C, 150-200mm rain. NSTR Tiger Reserve closed. Skip strict.',
  NULL,
  'June at Srisailam loses the safari side of the trip — NSTR Tiger Reserve closes June 1 through September for the southwest monsoon. The temple still runs but the Pathala Ganga ghat sees high-current Krishna river flows. October opens the proper window. Skip.',
  'June in Srisailam is the southwest monsoon onset. Rainfall climbs to 150-200mm across 10-12 wet days, daytime 32-33C, nights 24-25C, humidity 80 percent. Nagarjuna Sagar Srisailam Tiger Reserve (India''s largest at 3,568 sq km) closes for the monsoon June 1 through end-September — no jeep safari, no morning circuit. The Bhramaramba Mallikarjuna Swamy Temple continues at full ritual tempo; Suprabhata Seva 4:30am, the standard darshan through the day. The Pathala Ganga ghat 850-ft cable car descent sees the Krishna river running at high flow — the ghat itself becomes hazardous during heavy-rain bursts as the river-level fluctuates rapidly; cable car operations pause on storm days. Srisailam Dam at full reservoir build-up; the 124-gate masonry-and-NCC composite dam is at maximum visual impact through the late monsoon. The Nallamala forest road from Hyderabad (213km) and from Kurnool (180km) sees rain-day closure risk. APTDC Haritha rates at year-low: ₹2,500-4,500; private guest houses ₹700-1,800. The pilgrim-only trip works; the full Srisailam experience (temple + safari + ghat) cannot. October is materially better. Skip.'
)
