INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srisailam', 7, 1, 'skip',
  'SW monsoon peak. 23-31C, 250-350mm rain. NSTR closed. Krishna river in flood. Roads compromised.',
  NULL,
  'July is SW monsoon at peak across the Nallamala range. NSTR closed. Krishna river in flood (Pathala Ganga ghat hazardous). Forest roads compromised. Temple only viable — and that is not the trip. October opens the proper window.',
  'July in Srisailam is the southwest monsoon at peak. Rainfall climbs to 250-350mm across 14-16 wet days, daytime 30-31C, nights 23-24C, humidity 85 percent. The Nallamala range catches significant orographic rainfall — Srisailam is one of the wetter pockets of inland Andhra Pradesh in July. NSTR Tiger Reserve closed for the full month. The Bhramaramba Mallikarjuna Swamy Temple continues at full ritual tempo. The Pathala Ganga ghat at the Krishna river runs hazardous — the Krishna typically peaks at Srisailam in late July as upstream catchment dams (Almatti, Narayanpur in Karnataka) release water; the ghat itself can flood, and cable car operations are suspended on storm days. The 850-ft cable car (₹50 round trip) operates on dry-window mornings only. Srisailam Dam at near-full reservoir; the spillway gates begin opening as the reservoir reaches FRL (full reservoir level 269.74m). Forest road from Hyderabad and Kurnool sees rain-day closure risk on the Mannanur ghat section. APTDC Haritha rates at year-low: ₹2,200-4,200; private guest houses ₹600-1,500. Skip.'
)
