INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srisailam', 8, 2, 'skip',
  'Monsoon continues. 23-30C, 200-280mm rain. NSTR still closed. Dam spillway active. Push to October.',
  NULL,
  'August at Srisailam continues the SW monsoon. NSTR Tiger Reserve still closed. Krishna river in flood — Srisailam dam spillway gates open. The trip you came for cannot happen. October opens the proper window.',
  'August in Srisailam continues the southwest monsoon. Rainfall 200-280mm across 13-15 wet days, daytime 29-30C, nights 23-24C, humidity 85 percent. NSTR Tiger Reserve closed through September. The Bhramaramba Mallikarjuna Swamy Temple at full ritual tempo. The Pathala Ganga ghat at the Krishna river sees high-volume river-flow; cable car operations suspended on storm days. Srisailam Dam at full reservoir — typically the spillway gates open in August as the reservoir reaches FRL; the dam viewing platform shows the cascading 10-15 gate release, which is the year''s most dramatic dam visual but accessibility is restricted on heavy-release days. Forest road from Hyderabad and Kurnool sees periodic closure on the Mannanur ghat. Sravana-Sukravara (Sravana Fridays — Telugu calendar mid-August through mid-September) brings local pilgrim density; the temple sees regional Telugu-pilgrim cluster on each Sukravara despite the weather. APTDC Haritha rates at off-peak: ₹2,500-4,500; private guest houses ₹700-1,800. The dam-spillway-only trip works for civil-engineering enthusiasts. October-March is dramatically better for the full pilgrim-and-safari experience.'
)
