INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srisailam', 9, 4, 'go',
  'Monsoon retreats. 22-29C. NSTR reopens late Sep. Krishna river at peak volume. Last off-peak window.',
  'September is the bridge month. SW monsoon retreats through second half; NSTR Tiger Reserve reopens late September. Krishna river at peak post-monsoon volume — Srisailam dam at FRL. Last off-peak value window before October peak.',
  NULL,
  'September in Srisailam is the bridge month before the peak season opens. Rainfall drops to 130-180mm across 10-12 wet days as the southwest monsoon retreats from the Nallamala range (IMD typically declares formal SW retreat from coastal AP late September). Daytime 28-29C, nights 22-23C, humidity 80 percent. NSTR (Nagarjuna Sagar Srisailam Tiger Reserve — India''s largest at 3,568 sq km) reopens after the four-month monsoon closure — typically the gate reopens around September 25-30 depending on rainfall and the access road condition. The Bhramaramba Mallikarjuna Swamy Temple at full ritual tempo. The Pathala Ganga ghat 850-ft cable car descent (₹50 round trip) back at full schedule; the Krishna river runs at its annual maximum volume through September. Srisailam Dam typically at FRL through the month — spillway gate operations continue. Aatukur boat point (10km, boat rides on the dam reservoir) reopens late month. APTDC Haritha rates climb 20 percent off August: ₹3,000-5,200; private guest houses ₹900-2,300. Last off-peak value window before October peak season; September-end works for travelers wanting both the post-monsoon green Nallamala forest and the dam at peak visual scale.'
)
