INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srisailam', 11, 5, 'go',
  'NE monsoon active. 18-27C. Karthika Masam mass-deepam at Jyotirlinga. NSTR safari at year-peak visibility.',
  'November is the peak-build month. NE monsoon 150-200mm in evening showers. Karthika Masam (full month) brings mass-deepam at the Mallikarjuna Jyotirlinga. NSTR safari at year-peak visibility on receding water sources.',
  NULL,
  'November in Srisailam is one of the year''s peak months. Northeast monsoon active with 150-200mm rainfall across 9-11 wet days — late-afternoon and evening showers that rinse the Nallamala plateau without disrupting morning programmes. Daytime 26-27C, nights 18-19C, humidity 70 percent. The Bhramaramba Mallikarjuna Swamy Temple at full ritual tempo. Karthika Masam (the full Karthika lunar month — late October into late November in 2026, with Karthika Pournami the full-moon climax mid-November) brings mass-deepam observances at the Mallikarjuna Jyotirlinga; the temple is one of the four major Karthika-Deepam sites in Andhra alongside Srikalahasti, Lepakshi, and Tirumala. The 850-ft Pathala Ganga ghat cable car descent at full schedule; the Krishna river runs at clean post-monsoon flow. NSTR (Nagarjuna Sagar Srisailam Tiger Reserve) at year-peak wildlife visibility — the receding water sources begin to concentrate sambar, chital, gaur, and predator activity; morning and afternoon jeep safaris run at full schedule. Aatukur boat point at full operations. APTDC Haritha rates at peak: ₹4,000-6,500; private guest houses ₹1,300-3,000. Lock rooms 6-8 weeks ahead for Karthika Pournami window.'
)
