INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('srisailam', 12, 5, 'go',
  'Cool peak. 16-26C. NSTR safari at year-best wildlife concentration. Vaikunta Ekadasi tail Dec 30.',
  'December is the peak-cool month. Daytime 25-26C, nights 16-18C. NSTR safari at year-best wildlife visibility on dry-season water-source concentration. Christmas-NYE corridor brings family pilgrim density.',
  NULL,
  'December in Srisailam is the peak-cool month. Rainfall drops to 30-60mm as the northeast monsoon tails off through the first half; the second half is the year''s driest stretch. Daytime 25-26C, nights 16-18C, humidity 60 percent. The Bhramaramba Mallikarjuna Swamy Temple at full ritual tempo; the cool stone interior holds 22-24C and the temple''s outer prakaram walks cleanly through the full day. The Pathala Ganga ghat 850-ft cable car descent (₹50 round trip) at full schedule with the Krishna river at clean post-monsoon flow. NSTR (Nagarjuna Sagar Srisailam Tiger Reserve — India''s largest at 3,568 sq km) at year-best wildlife visibility — the dry-season water-source concentration peaks through December-February, when tiger sightings, leopard tracks, and the sambar-gaur-chital ungulate concentration cluster at the limited waterholes; morning and afternoon jeep safaris (₹500-800 per seat shared, ₹3,500-5,000 private) book out 2-3 weeks ahead. Srisailam Dam viewing platform clean through the day. Christmas-NYE corridor (Dec 22 to Jan 5) brings Andhra and Telangana family pilgrim density. APTDC Haritha at peak: ₹4,200-6,800; private guest houses ₹1,400-3,200.'
)
